    hdr_comp_len:add_proto_expert_info(ef_error, "out of region bounds in comp_len.plen")
    return off
  end
  if off + 8 > avail then
    hdr_comp_len:add_proto_expert_info(ef_error, "out of bounds in comp_len.plen")
    return off
  end
  v.v_comp_len_plen = buf():bitfield(off, 8)
  hdr_comp_len:add(pf.f_comp_len_plen, buf(math.floor(off / 8), math.floor((off % 8 + 8 + 7) / 8)), v.v_comp_len_plen)
  off = off + 8
  if v.v_comp_len_plen == 0 then
    tree:add_proto_expert_info(ef_error, "empty compressions")
    return off
  else
    return states.s_comp(buf, pinfo, tree, off, depth, meta, regions)
  end
end

function states.s_comp(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_comp = tree:add(pf.f_hdr_comp, buf(math.floor(off / 8)))
  local len_comp_body = (v.v_comp_len_plen * 8)
  if regions[#regions] and (len_comp_body < 0 or off + len_comp_body > regions[#regions]) then
    hdr_comp:add_proto_expert_info(ef_error, "out of region bounds in comp.body")
    return off
  end
  if len_comp_body < 0 or off + len_comp_body > avail then
    hdr_comp:add_proto_expert_info(ef_error, "out of bounds in comp.body")
    return off
  end
  if len_comp_body > 0 then
    hdr_comp:add(pf.f_comp_body, buf(math.floor(off / 8), math.floor(len_comp_body / 8)))
  end
  off = off + len_comp_body
  return states.s_ext_check(buf, pinfo, tree, off, depth, meta, regions)
end

function states.s_ext_check(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  if math.floor((regions[#regions] - off) / 2 ^ 3) == 0 then
    return states.s_done_noext(buf, pinfo, tree, off, depth, meta, regions)
  elseif math.floor((regions[#regions] - off) / 2 ^ 3) == 1 then
    tree:add_proto_expert_info(ef_error, "partial extensions length")
    return off
  else
    return states.s_ext_len(buf, pinfo, tree, off, depth, meta, regions)
  end
end

function states.s_ext_len(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_ext_len = tree:add(pf.f_hdr_ext_len, buf(math.floor(off / 8)))
  if regions[#regions] and off + 16 > regions[#regions] then
    hdr_ext_len:add_proto_expert_info(ef_error, "out of region bounds in ext_len.total")
    return off
  end
  if off + 16 > avail then
    hdr_ext_len:add_proto_expert_info(ef_error, "out of bounds in ext_len.total")
    return off
  end
  v.v_ext_len_total = buf():bitfield(off, 16)
  hdr_ext_len:add(pf.f_ext_len_total, buf(math.floor(off / 8), math.floor((off % 8 + 16 + 7) / 8)), v.v_ext_len_total)
  off = off + 16
  do
    local rlen = (v.v_ext_len_total * 8)
    if rlen < 0 or (regions[#regions] and off + rlen > regions[#regions]) then
      tree:add_proto_expert_info(ef_error, "region out of bounds")
      return off
    end
    regions[#regions + 1] = off + rlen
  end
  return states.s_tlv(buf, pinfo, tree, off, depth, meta, regions)
end

function states.s_tlv(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  if math.floor((regions[#regions] - off) / 2 ^ 3) == 0 then
    return states.s_done(buf, pinfo, tree, off, depth, meta, regions)
  elseif math.floor((regions[#regions] - off) / 2 ^ 3) == 1 then
    tree:add_proto_expert_info(ef_error, "partial extension header")
    return off
  elseif math.floor((regions[#regions] - off) / 2 ^ 3) == 2 then
    tree:add_proto_expert_info(ef_error, "partial extension header")
    return off
  elseif math.floor((regions[#regions] - off) / 2 ^ 3) == 3 then
    tree:add_proto_expert_info(ef_error, "partial extension header")
    return off
  else
    return states.s_ext(buf, pinfo, tree, off, depth, meta, regions)
  end
end

function states.s_ext(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_ext = tree:add(pf.f_hdr_ext, buf(math.floor(off / 8)))
  if regions[#regions] and off + 16 > regions[#regions] then
    hdr_ext:add_proto_expert_info(ef_error, "out of region bounds in ext.typ")
    return off
  end
  if off + 16 > avail then
    hdr_ext:add_proto_expert_info(ef_error, "out of bounds in ext.typ")
    return off
  end
  v.v_ext_typ = buf():bitfield(off, 16)
  hdr_ext:add(pf.f_ext_typ, buf(math.floor(off / 8), math.floor((off % 8 + 16 + 7) / 8)), v.v_ext_typ)
  off = off + 16
  if regions[#regions] and off + 16 > regions[#regions] then
    hdr_ext:add_proto_expert_info(ef_error, "out of region bounds in ext.elen")
    return off
  end
  if off + 16 > avail then
    hdr_ext:add_proto_expert_info(ef_error, "out of bounds in ext.elen")
    return off
  end
  v.v_ext_elen = buf():bitfield(off, 16)
  hdr_ext:add(pf.f_ext_elen, buf(math.floor(off / 8), math.floor((off % 8 + 16 + 7) / 8)), v.v_ext_elen)
  off = off + 16
  if v.v_ext_typ == 0 and meta.seen_sni == 0 then
    return states.s_sni(buf, pinfo, tree, off, depth, meta, regions)
  elseif v.v_ext_typ == 0 and meta.seen_sni == 1 then
    tree:add_proto_expert_info(ef_error, "duplicate sni")
    return off
  else
    return states.s_skip(buf, pinfo, tree, off, depth, meta, regions)
  end
end

function states.s_skip(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_skip = tree:add(pf.f_hdr_skip, buf(math.floor(off / 8)))
  local len_skip_body = (v.v_ext_elen * 8)
  if regions[#regions] and (len_skip_body < 0 or off + len_skip_body > regions[#regions]) then
    hdr_skip:add_proto_expert_info(ef_error, "out of region bounds in skip.body")
    return off
  end
  if len_skip_body < 0 or off + len_skip_body > avail then
    hdr_skip:add_proto_expert_info(ef_error, "out of bounds in skip.body")
    return off
  end
  if len_skip_body > 0 then
    hdr_skip:add(pf.f_skip_body, buf(math.floor(off / 8), math.floor(len_skip_body / 8)))
  end
  off = off + len_skip_body
  return states.s_tlv(buf, pinfo, tree, off, depth, meta, regions)
end

function states.s_sni(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  meta.seen_sni = (1) % 2^1
  do
    local rlen = (v.v_ext_elen * 8)
    if rlen < 0 or (regions[#regions] and off + rlen > regions[#regions]) then
      tree:add_proto_expert_info(ef_error, "region out of bounds")
      return off
    end
    regions[#regions + 1] = off + rlen
  end
  return states.s_sni_list(buf, pinfo, tree, off, depth, meta, regions)
end

function states.s_sni_list(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
