end

function states.s_sni_entry(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_sni_entry = tree:add(pf.f_hdr_sni_entry, buf(math.floor(off / 8)))
  if regions[#regions] and off + 8 > regions[#regions] then
    hdr_sni_entry:add_proto_expert_info(ef_error, "out of region bounds in sni_entry.ntype")
    return off
  end
  if off + 8 > avail then
    hdr_sni_entry:add_proto_expert_info(ef_error, "out of bounds in sni_entry.ntype")
    return off
  end
  v.v_sni_entry_ntype = buf():bitfield(off, 8)
  hdr_sni_entry:add(pf.f_sni_entry_ntype, buf(math.floor(off / 8), math.floor((off % 8 + 8 + 7) / 8)), v.v_sni_entry_ntype)
  off = off + 8
  if regions[#regions] and off + 16 > regions[#regions] then
    hdr_sni_entry:add_proto_expert_info(ef_error, "out of region bounds in sni_entry.hlen")
    return off
  end
  if off + 16 > avail then
    hdr_sni_entry:add_proto_expert_info(ef_error, "out of bounds in sni_entry.hlen")
    return off
  end
  v.v_sni_entry_hlen = buf():bitfield(off, 16)
  hdr_sni_entry:add(pf.f_sni_entry_hlen, buf(math.floor(off / 8), math.floor((off % 8 + 16 + 7) / 8)), v.v_sni_entry_hlen)
  off = off + 16
  if v.v_sni_entry_ntype == 0 then
    return states.s_host(buf, pinfo, tree, off, depth, meta, regions)
  else
    tree:add_proto_expert_info(ef_error, "unsupported sni name type")
    return off
  end
end

function states.s_host(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  local hdr_host = tree:add(pf.f_hdr_host, buf(math.floor(off / 8)))
  local len_host_name = (v.v_sni_entry_hlen * 8)
  if regions[#regions] and (len_host_name < 0 or off + len_host_name > regions[#regions]) then
    hdr_host:add_proto_expert_info(ef_error, "out of region bounds in host.name")
    return off
  end
  if len_host_name < 0 or off + len_host_name > avail then
    hdr_host:add_proto_expert_info(ef_error, "out of bounds in host.name")
    return off
  end
  if len_host_name > 0 then
    hdr_host:add(pf.f_host_name, buf(math.floor(off / 8), math.floor(len_host_name / 8)))
  end
  off = off + len_host_name
  do
    local rend = table.remove(regions)
    if off < rend then
      tree:add_proto_expert_info(ef_error, "region not exhausted")
      return off
    end
  end
  do
    local rend = table.remove(regions)
    if off < rend then
      tree:add_proto_expert_info(ef_error, "region not exhausted")
      return off
    end
  end
  return states.s_tlv(buf, pinfo, tree, off, depth, meta, regions)
end

function states.s_done(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  do
    local rend = table.remove(regions)
    if off < rend then
      tree:add_proto_expert_info(ef_error, "region not exhausted")
      return off
    end
  end
  do
    local rend = table.remove(regions)
    if off < rend then
      tree:add_proto_expert_info(ef_error, "region not exhausted")
      return off
    end
  end
  do
    local rend = table.remove(regions)
    if off < rend then
      tree:add_proto_expert_info(ef_error, "region not exhausted")
      return off
    end
  end
  tree:add(pf.f_meta_seen_sni, UInt64(meta.seen_sni))
  tree:add(pf.f_meta_cs_odd, UInt64(meta.cs_odd))
  add_payload(buf, tree, off)
  return off
end

function states.s_done_noext(buf, pinfo, tree, off, depth, meta, regions)
  depth = depth + 1
  if depth > 96 then
    tree:add_proto_expert_info(ef_error, "max depth exceeded")
    return off
  end
  local avail = buf:len() * 8
  do
    local rend = table.remove(regions)
    if off < rend then
      tree:add_proto_expert_info(ef_error, "region not exhausted")
      return off
    end
  end
  do
    local rend = table.remove(regions)
    if off < rend then
      tree:add_proto_expert_info(ef_error, "region not exhausted")
      return off
    end
  end
  tree:add(pf.f_meta_seen_sni, UInt64(meta.seen_sni))
  tree:add(pf.f_meta_cs_odd, UInt64(meta.cs_odd))
  add_payload(buf, tree, off)
  return off
end

function p.dissector(buf, pinfo, tree)
  local root = tree:add(p, buf())
  local meta = { seen_sni = 0, cs_odd = 0 }
  states.s_record(buf, pinfo, root, 0, 0, meta, {})
end

-- Postdissector: runs on every frame after built-in dissection,
-- so our tree appears alongside Wireshark's own — side-by-side
-- comparison for free, no dissector-table precedence fights.
register_postdissector(p)
